N=17; m=N//2
G=[[0]*N for _ in range(N)]
for r in range(N):
    for s in range(0,m+1,2):
        c=m+r-2*s
        if r>s and 0<=c<N: G[r][c]=1
    if r<=m:
        G[r][m-r]=2; G[r][m+r]=2
print(G)

N=17; m=N//2
G2=[[0]*N for _ in range(N)]
for r in range(N):
    for k in range(1, 10):
        c=r+m-4*k
        if r>=2*k+1 and 0<=c<N: G2[r][c]=1
    if r<=m:
        G2[r][m-r]=2; G2[r][m+r]=2
print(G2)
